from pathlib import Path
from html import escape
R=Path(__file__).parent
nav='<a href="/">Home</a><a href="/project/">Projects</a><a href="/services/">Services</a><a href="/news/">News</a><a href="/about/">About</a><a href="/press/">Press</a><a href="/contact/">Contact</a>'
languages='<div class="lang"><a href="/" lang="en">EN</a><a href="/zh-hant/" lang="zh-Hant">繁</a><a href="/zh-hans/" lang="zh-Hans">简</a><a href="/ja/" lang="ja">日</a><a href="/ko/" lang="ko">한</a></div>'
def page(title,description,content,filename):
 alternates = '<link rel="alternate" hreflang="en" href="https://www.aurora-studio.org/"><link rel="alternate" hreflang="zh-Hant" href="https://www.aurora-studio.org/zh-hant/"><link rel="alternate" hreflang="zh-Hans" href="https://www.aurora-studio.org/zh-hans/"><link rel="alternate" hreflang="ja" href="https://www.aurora-studio.org/ja/"><link rel="alternate" hreflang="ko" href="https://www.aurora-studio.org/ko/">' if filename == 'index.html' else ''
 schema = '<script type="application/ld+json">{"@context":"https://schema.org","@type":"Organization","@id":"https://www.aurora-studio.org/#organization","name":"Aurora Studio","url":"https://www.aurora-studio.org/","description":"Hong Kong independent game studio developing simulation games, supernatural narrative experiences and game technology.","knowsAbout":["Video Game Development","Simulation Games","Unreal Engine","Godot","C++","Game AI","NPC Simulation","3D Environment Art","Japanese Folklore"]}</script>' if filename == 'index.html' else ''
 project_schema = ''
 if filename.startswith('project/') and filename != 'project/index.html':
  entity_name = {'project/project-numazu/index.html':'Project Numazu','project/revenant-of-tsushima/index.html':'Revenant of Tsushima','project/railway-depot/index.html':'Railway Depot: Operations & Empire','project/aurora-engine/index.html':'Aurora Engine'}.get(filename)
  if entity_name:
   entity_type = 'SoftwareSourceCode' if entity_name == 'Aurora Engine' else 'VideoGame'
   entity_url = 'https://www.aurora-studio.org/' + filename.replace('index.html','')
   project_schema = f'<script type="application/ld+json">{{"@context":"https://schema.org","@type":"{entity_type}","@id":"{entity_url}#entity","name":"{entity_name}","url":"{entity_url}","creator":{{"@id":"https://www.aurora-studio.org/#organization"}}}}</script>'
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(description)}"><link rel="canonical" href="https://www.aurora-studio.org/{filename.replace('index.html','')}">{alternates}{schema}{project_schema}<link rel="icon" href="/assets/aurora-studio-icon.png?v=20260925" type="image/png"><link rel="apple-touch-icon" href="/assets/aurora-studio-icon.png"><link rel="stylesheet" href="/style.css?v=20260925k"></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a href="/" class="brand" aria-label="Aurora Studio home"><span class="brand-mark" aria-hidden="true"><img src="/assets/aurora-studio-logo.jpeg" alt="" width="1500" height="1000"></span><span class="brand-name">Aurora Studio</span></a><nav aria-label="Main navigation">{nav}</nav>{languages}<a class="header-contact" href="mailto:press@aurora-studio.org">Get in touch <span aria-hidden="true">↗</span></a></header><main id="main">{content}</main><footer><div><strong>AURORA STUDIO</strong><p>Independent game development · Hong Kong</p></div><div><a href="/project/">Projects</a><a href="/services/">Services</a><a href="/news/">News</a><a href="/support/">Support</a><a href="/governance/">Governance</a><a href="/contact/">Contact</a></div><small>© 2026 Aurora Studio</small></footer></body></html>'''
 p=R/filename;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(html)
page('Aurora Studio | Hong Kong Independent Game Studio','Aurora Studio is a Hong Kong independent game studio developing Project Numazu, Revenant of Tsushima, Railway Depot and Aurora Engine.','''<section class="hero"><img class="hero-image" src="/assets/numazu-buses.jpg" alt="Two buses in the Project Numazu game environment" fetchpriority="high"><div class="hero-shade"></div><div class="hero-content"><p class="eyebrow">INDEPENDENT GAME STUDIO · HONG KONG</p><h1>Places worth<br><em>getting lost in.</em></h1><p>Aurora Studio is a Hong Kong independent game studio building simulation games, supernatural narrative experiences and game technology shaped by the places, stories and streets of East Asia.</p><div class="actions"><a class="button light" href="/project/">Explore our projects <span aria-hidden="true">↗</span></a><a class="text-link" href="/about/">Meet the studio <span aria-hidden="true">→</span></a></div></div><div class="hero-caption">01 / OMSI 2 ADD-ON: PROJECT NUMAZU</div></section><section class="section intro"><div><p class="eyebrow dark">WHAT WE MAKE</p><h2>Built with a sense<br>of place.</h2></div><p>From Project Numazu, our OMSI 2 recreation of Numazu in Shizuoka, to Revenant of Tsushima, Railway Depot: Operations & Empire and Aurora Engine, we create place-driven worlds, simulation systems and experimental game technology.</p></section><section class="section projects"><div class="section-head"><p class="eyebrow dark">SELECTED WORK</p><a href="/project/">All projects ↗</a></div><div class="project-grid"><a class="feature-card" href="/project/project-numazu/"><img src="/assets/numazu-route.jpg" alt="Bus travelling through a Project Numazu street" loading="lazy"><div><span>SIMULATION · RELEASED</span><h3>Project Numazu</h3><p>A carefully reconstructed Japanese city for OMSI 2.</p><b aria-hidden="true">↗</b></div></a><a class="type-card" href="/project/revenant-of-tsushima/"><img class="rot-card-image" src="/assets/revenant-cover-clean.jpg" alt="Revenant of Tsushima poster with Tsushima Mewa and supernatural figures under a moonlit sky" loading="lazy"><span>NARRATIVE HORROR · IN DEVELOPMENT</span><h3>Revenant of Tsushima</h3><p>An Edo-era folk horror journey through memory, ritual and the supernatural.</p><b aria-hidden="true">↗</b></a></div></section><section class="section home-extras"><div class="info-panel"><p class="eyebrow dark">COLLABORATE</p><h2>Build with us.</h2><p>Environment production, simulation design and game prototypes informed by years of work on place-based worlds.</p><a href="/services/">Explore services ↗</a></div><div class="info-panel"><p class="eyebrow dark">SUPPORT THE STUDIO</p><h2>Help keep our worlds growing.</h2><p>Follow development and support independent production through the Aurora Studio Supporters Club.</p><a href="/support/">Ways to support ↗</a></div></section><section class="callout"><p class="eyebrow">LET'S CONNECT</p><h2>Have a story to tell<br>or a world to build?</h2><a class="button light" href="/contact/">Contact the studio ↗</a></section>''','index.html')
page('Projects','Explore Project Numazu, Revenant of Tsushima, Railway Depot and Aurora Engine.','''<section class="page-heading"><p class="eyebrow dark">OUR WORK</p><h1>Projects<span class="dot">.</span></h1><p>Simulated places, lived-in systems and stories from East Asia.</p></section><section class="section project-list"><article class="listing"><img src="/assets/numazu-buses.jpg" alt="Two buses in Project Numazu"><div><span class="eyebrow dark">01 / SIMULATION · RELEASED</span><h2>OMSI 2: Project Numazu</h2><p>Drive through a 1:1 scale recreation of Numazu, Shizuoka, from its station district to the coastal landmarks and everyday streets around it.</p><a href="/project/project-numazu/">Explore Project Numazu ↗</a></div></article><article class="listing alt"><img class="rot-list-art" src="/assets/revenant-cover-clean.jpg" alt="Revenant of Tsushima poster" loading="lazy"><div><span class="eyebrow dark">02 / FOLK HORROR · IN DEVELOPMENT</span><h2>Revenant of Tsushima</h2><p>A first-person journey through an Edo-period Japan reshaped by the awakening of Tsushima Mewa, a shrine maiden sealed for more than three centuries.</p><a href="/project/revenant-of-tsushima/">Visit official project site ↗</a></div></article><article class="mini-list"><span>03 / MANAGEMENT SIMULATION</span><h2>Railway Depot: Operations &amp; Empire</h2><p>Run the railway behind the trains: depot operations, maintenance and dispatch.</p><a href="/project/railway-depot/">Explore the project ↗</a></article><article class="mini-list"><span>04 / TECHNOLOGY</span><h2>Aurora Engine</h2><p>A modular C++ and Unreal framework for NPC perception, memory and decisions.</p><a href="/project/aurora-engine/">Explore the project ↗</a></article></section>''','project/index.html')
page('Project Numazu | OMSI 2 Japanese Bus Simulation | Aurora Studio','Project Numazu is Aurora Studio’s OMSI 2 add-on recreating Numazu, Shizuoka, with Japanese bus routes, streets and coastal scenery.','''<section class="project-hero"><img src="/assets/numazu-buses.jpg" alt="Japanese buses in the Project Numazu game environment"><div><p class="eyebrow">OMSI 2 ADD-ON · AVAILABLE ON STEAM</p><h1>Project<br>Numazu.</h1><p>A journey into the streets and coastal scenery of Numazu, Shizuoka.</p><a class="button light" href="https://store.steampowered.com/app/3880120/">View on Steam ↗</a></div></section><section class="section prose"><p class="eyebrow dark">THE PROJECT</p><h2>Japan, one route at a time.</h2><p>Project Numazu brings the city’s urban core, bus routes and coastal atmosphere into OMSI 2. The team recreated familiar landmarks, streets and transit details to give players a place that feels grounded in everyday life.</p><p>Developed by Aurora Studio with collaborators including Negi-Kyu Workshop. Released March 2026.</p><div class="gallery"><img src="/assets/numazu-route.jpg" alt="Numazu city streets recreated in OMSI 2" loading="lazy"><img src="/assets/numazu-station.jpg" alt="Bus in the Numazu Station area" loading="lazy"></div><a href="/project/">← All projects</a></section>''','project/project-numazu/index.html')
page('About','Aurora Studio is an independent game development team based in Hong Kong.','''<section class="page-heading"><p class="eyebrow dark">ABOUT THE STUDIO</p><h1>Made in Hong Kong.<br><em>Inspired by Asia.</em></h1><p>Aurora Studio is an independent game development team based in Hong Kong.</p></section><section class="section two-column"><h2>Who we are</h2><div><p>We craft simulation and narrative-driven experiences inspired by Asia, combining cultural detail with technical precision.</p><p>Founded by Shiko Leung, the studio works with creators and partners across disciplines to bring local places and original stories to a global audience.</p><h3>Shiko Leung</h3><p>Founder &amp; Creative Director<br>Game direction, environment design, production and studio operations.</p></div></section><section class="callout"><p class="eyebrow">WORK WITH US</p><h2>Let's make something<br>memorable.</h2><a class="button light" href="/contact/">Contact the studio ↗</a></section>''','about/index.html')
page('News','Updates from Aurora Studio and its game projects.','''<section class="page-heading"><p class="eyebrow dark">FROM THE STUDIO</p><h1>News<span class="dot">.</span></h1><p>Selected announcements and milestones. Earlier articles are being restored from the previous website.</p></section><section class="section news-list"><article><time datetime="2026-09-17">17 SEP 2026</time><div><span>PROJECT UPDATE</span><h2>A Day in the Depot: Railway Depot: Operations &amp; Empire</h2><p>Introducing a management simulation about the work that keeps a railway running.</p><a href="/news/a-day-in-the-depot/">Read update ↗</a></div></article><article><time datetime="2026-03-30">30 MAR 2026</time><div><span>RELEASE</span><h2>Project Numazu is available on Steam</h2><p>Aurora Studio’s recreation of Numazu for OMSI 2 has launched.</p><a href="/news/project-numazu-is-officially-available-on-steam/">Read update ↗</a></div></article><article><time datetime="2025-12-01">01 DEC 2025</time><div><span>PROJECT UPDATE</span><h2>Project Numazu Steam page goes live</h2><p>The public store page introduced the team’s Japanese city simulation to players.</p><a href="/news/omsi-2-add-on-project-numazu-steam-page-now-live/">Read update ↗</a></div></article></section>''','news/index.html')
page('Contact','Get in touch with Aurora Studio for press, partnerships and project enquiries.','''<section class="page-heading"><p class="eyebrow dark">CONTACT</p><h1>Let's talk<span class="dot">.</span></h1><p>For coverage, partnerships or a conversation about our work, write to the studio directly.</p></section><section class="section contact-grid"><a href="mailto:press@aurora-studio.org"><span>PRESS &amp; PARTNERSHIPS</span><h2>press@aurora-studio.org</h2><b>↗</b></a><a href="mailto:support@aurora-studio.org"><span>PLAYER SUPPORT</span><h2>support@aurora-studio.org</h2><b>↗</b></a></section>''','contact/index.html')
page('Revenant of Tsushima | Japanese Folk Horror Game | Aurora Studio','Revenant of Tsushima is Aurora Studio’s Unreal Engine 5 first-person Japanese folk horror game starring Tsushima Mewa.','''<figure class="rot-poster"><img src="/assets/revenant-cover-v2.jpg" alt="Revenant of Tsushima artwork featuring Tsushima Mewa, spirits and a moonlit Japanese landscape" fetchpriority="high"></figure><section class="page-heading"><p class="eyebrow dark">ORIGINAL GAME · IN DEVELOPMENT</p><h1>Revenant of<br>Tsushima<span class="dot">.</span></h1><p>Japanese folk horror on a journey through the Tōkaidō.</p></section><section class="section two-column"><h2>A world awakened</h2><div><p>Tsushima Mewa, a shrine maiden sealed for more than three centuries, awakens to a world of yōkai. The player travels through shrines, villages, mountain passes and the coast, using Ether Sight and rituals to face supernatural threats.</p><p>This original first-person project is in development in Unreal Engine 5. Game features and scope may change.</p><a class="button light" href="https://revenant-tsushima.aurora-studio.org/">Official game website ↗</a></div></section>''','project/revenant-of-tsushima/index.html')
page('Railway Depot: Operations & Empire | Railway Management Game','Railway Depot: Operations & Empire is Aurora Studio’s railway operations and management simulation about depots, maintenance, staff and dispatch.','''<section class="page-heading"><p class="eyebrow dark">MANAGEMENT SIM · PRE-ALPHA</p><h1>Railway<br>Depot<span class="dot">.</span></h1><p>You don't just drive the trains. You run the railway behind them.</p></section><section class="section two-column"><h2>Run the day behind the trains.</h2><div><p>Prepare trains, coordinate maintenance, assign people and dispatch services. Railway Depot: Operations &amp; Empire is an early-stage operations and management game inspired by East Asian railway culture.</p><p>A pre-alpha build is available for feedback. Systems and visuals are subject to change.</p><a class="button light" href="https://shikosama.itch.io/railway-depot">Explore on itch.io ↗</a></div></section>''','project/railway-depot/index.html')
page('Aurora Engine | NPC Perception, Memory & Decision Framework','Aurora Engine is Aurora Studio’s modular C++ and Unreal framework for NPC perception, knowledge, memory, information propagation and decision-making.','''<section class="page-heading"><p class="eyebrow dark">R&amp;D · OPEN DEVELOPMENT</p><h1>Aurora Engine<span class="dot">.</span></h1><p>A modular framework for agents that see, learn, remember and act.</p></section><section class="section two-column"><h2>Systems for lived-in worlds.</h2><div><p>Aurora Engine explores how game characters perceive their surroundings, retain knowledge and make decisions within a designer-directed world. The project includes a C++ core and Unreal integration work.</p><p>This is active research and development, not a shipped game.</p><a class="button light" href="https://github.com/Shiko215/aurora-engine">See the source ↗</a></div></section>''','project/aurora-engine/index.html')
news_items=[
('a-day-in-the-depot','A Day in the Depot: Announcing Railway Depot: Operations & Empire','2026-09-17','Project update','Aurora Studio announced a railway management simulation about the rolling stock, people and decisions behind daily depot operations. A pre-alpha build is available for feedback on itch.io.','/project/railway-depot/'),
('project-numazu-is-officially-available-on-steam','Project Numazu is available on Steam','2026-03-30','Release','The OMSI 2 add-on brings a detailed recreation of Numazu, Shizuoka, to bus simulation players. It is Aurora Studio’s first commercial release.','/project/project-numazu/'),
('omsi-2-add-on-project-numazu-steam-page-now-live','Project Numazu Steam page goes live','2025-12-01','Project update','The store page introduced Project Numazu’s Japanese bus simulation, city streets and coastal atmosphere ahead of its March 2026 release.','/project/project-numazu/'),
('project-numazu-tga-2026-fyc','Project Numazu begins a TGA 2026 For Your Consideration campaign','2026-09-04','Studio update','Aurora Studio announced a campaign for consideration in The Game Awards 2026 Best Sim / Strategy category. This is a campaign announcement; it does not indicate a nomination.','/project/project-numazu/')]
for slug,title,date,category,summary,link in news_items:
 content=f'''<section class="page-heading"><p class="eyebrow dark">{category.upper()} · <time datetime="{date}">{date}</time></p><h1 class="article-title">{title}</h1></section><article class="section article"><p class="archive-label">Migration summary · Aurora Studio</p><p>{summary}</p><p>This concise summary preserves the earlier article address while the full archive is being restored.</p><a href="{link}">Explore the project ↗</a><a href="/news/">← All news</a></article>'''
 page(title,summary,content,f'news/{slug}/index.html')
page('News','Updates from Aurora Studio and its game projects.','''<section class="page-heading"><p class="eyebrow dark">FROM THE STUDIO</p><h1>News<span class="dot">.</span></h1><p>Studio announcements and project milestones. Selected older articles currently show concise migration summaries.</p></section><section class="section news-list"><article><time datetime="2026-09-17">17 SEP 2026</time><div><span>PROJECT UPDATE</span><h2>A Day in the Depot: Railway Depot: Operations &amp; Empire</h2><p>An operations game about the people and decisions behind the railway.</p><a href="/news/a-day-in-the-depot/">Read update ↗</a></div></article><article><time datetime="2026-09-04">04 SEP 2026</time><div><span>STUDIO UPDATE</span><h2>Project Numazu TGA 2026 For Your Consideration campaign</h2><p>The studio announced its consideration campaign; this is not a nomination.</p><a href="/news/project-numazu-tga-2026-fyc/">Read update ↗</a></div></article><article><time datetime="2026-03-30">30 MAR 2026</time><div><span>RELEASE</span><h2>Project Numazu is available on Steam</h2><a href="/news/project-numazu-is-officially-available-on-steam/">Read update ↗</a></div></article><article><time datetime="2025-12-01">01 DEC 2025</time><div><span>PROJECT UPDATE</span><h2>Project Numazu Steam page goes live</h2><a href="/news/omsi-2-add-on-project-numazu-steam-page-now-live/">Read update ↗</a></div></article></section>''','news/index.html')
page('Services','Aurora Studio provides game environment, simulation and interactive prototype collaboration.','''<section class="page-heading"><p class="eyebrow dark">WORK WITH AURORA</p><h1>Services<span class="dot">.</span></h1><p>Selected creative and technical collaboration for games, simulation and place-based interactive experiences.</p></section><section class="section service-intro"><h2>From a real place to a playable world.</h2><p>Our work on Project Numazu brought together location research, 3D environment production and the constraints of a working transport simulator. We apply that experience to scoped collaborations with studios and cultural partners.</p></section><section class="section service-grid"><article><span>01 / ENVIRONMENTS</span><h2>Location-based 3D worlds</h2><p>Research-led world building, streetscapes and landmarks for interactive projects. Scope and source material are agreed per project.</p></article><article><span>02 / SIMULATION</span><h2>Systems and playable routes</h2><p>Simulation maps, route design and experience planning grounded in how places actually work.</p></article><article><span>03 / PROTOTYPING</span><h2>Game and NPC prototypes</h2><p>Early Unreal Engine gameplay and NPC system experiments, with clear boundaries between working prototypes and production features.</p></article><article><span>04 / INTERNATIONAL COLLABORATION</span><h2>Production coordination</h2><p>Creative briefs and cross-region coordination for project partners, contributors and media activity when it fits the project.</p></article></section><section class="callout"><p class="eyebrow">TELL US ABOUT YOUR PROJECT</p><h2>Start with the scope.</h2><p>Share the goal, timeline, budget range and what you need delivered. We will discuss availability and a suitable brief.</p><a class="button light" href="mailto:press@aurora-studio.org?subject=Aurora%20Studio%20collaboration%20enquiry">Discuss a collaboration ↗</a></section>''','services/index.html')
page('Support Aurora Studio','Support Aurora Studio through its membership community or discuss sponsorship and financing.','''<section class="page-heading"><p class="eyebrow dark">SUPPORT INDEPENDENT DEVELOPMENT</p><h1>Keep Aurora<br>creating<span class="dot">.</span></h1><p>Independent game development takes time, people and a runway. There are a few practical ways to help us keep building.</p></section><section class="section support-grid"><article><span>01 / COMMUNITY</span><h2>Join the Supporters Club</h2><p>Follow project updates and support the studio through the membership options shown on our Patreon page. Check the current benefits and terms there before joining.</p><a href="https://member.aurora-studio.org/">Explore memberships ↗</a></article><article><span>02 / PARTNERS</span><h2>Sponsor a project</h2><p>We welcome conversations about project sponsorship, exhibition support and cultural partnerships. We will agree credit, scope and deliverables in writing.</p><a href="mailto:press@aurora-studio.org?subject=Project%20sponsorship%20enquiry">Contact the studio ↗</a></article><article><span>03 / FINANCING</span><h2>Discuss bridge financing</h2><p>For qualified funding partners, we can discuss short-term development or operating finance privately, subject to due diligence and written terms.</p><a href="mailto:press@aurora-studio.org?subject=Bridge%20financing%20enquiry">Start a private enquiry ↗</a></article></section><section class="section support-note"><p>Memberships support ongoing work; they do not convey ownership in a game or the studio. Sponsorship and financing terms are agreed separately.</p></section>''','support/index.html')
page('Governance','Aurora Studio working principles for respectful collaboration, safety and responsible communication.','''<section class="page-heading"><p class="eyebrow dark">HOW WE WORK</p><h1>Governance<span class="dot">.</span></h1><p>Our public working principles for a small independent studio and its collaborators.</p></section><section class="section governance-intro"><p>We aim to give contributors, partners and community members a safe and respectful way to work with Aurora Studio. These principles guide our decisions; they are not a claim of external certification or a substitute for a project contract.</p></section><section class="section governance-list"><article><h2>Respect and equal treatment</h2><p>We oppose discrimination, harassment and online bullying. Work decisions should be based on relevant skills, conduct and project needs.</p></article><article><h2>Speak up without retaliation</h2><p>People may raise concerns about conduct, safety or unfair treatment. We will review concerns in good faith and do not accept retaliation for reporting them.</p></article><article><h2>Contributor and supplier standards</h2><p>We expect clear briefs, agreed payment terms, respect for intellectual property and lawful working arrangements. We ask suppliers and collaborators to follow the same principles.</p></article><article><h2>Safety and responsible production</h2><p>We plan location work, events and production tasks with practical safety needs in mind. We flag foreseeable risks and agree responsibilities before work begins.</p></article><article><h2>Data and business ethics</h2><p>We use contact information for relevant enquiries and project communication, limit access to people who need it, and avoid sharing confidential business information without authority.</p></article><article><h2>Concerns and follow-up</h2><p>Send a concern to <a href="mailto:press@aurora-studio.org?subject=Confidential%20studio%20concern">press@aurora-studio.org</a> with enough detail for us to review it. We will acknowledge and assess the matter, seek relevant information and explain the outcome where appropriate. This mailbox is managed by the studio, so it is not an independent reporting channel.</p></article></section>''','governance/index.html')

