for item in news_updates:
    paragraphs = ''.join(f'<p>{escape(p)}</p>' for p in item['paragraphs'])
    image = f'<img class="article-visual" src="{item["image"]}" alt="{escape(item["title"])}" loading="lazy">' if item['image'] else ''
    content = (f'<section class="page-heading news-heading"><p class="eyebrow dark">{escape(item["category"].upper())} · '
               f'<time datetime="{item["date"]}">{item["date"]}</time></p><h1 class="article-title">{escape(item["title"])}</h1>'
               f'<p>{escape(item["summary"])}</p></section><article class="section article">{image}{paragraphs}'
               f'<div class="article-links"><a href="{item["source"]}">{escape(item["source_label"])} ↗</a>'
               f'<a href="{item["project"]}">Explore the project ↗</a><a href="/news/">← All news</a></div></article>')
    page(item['title'], item['summary'], content, f'news/{item["slug"]}/index.html')

